      hu: ["Manatuszok", "Nyugodt folyoi viz", "Tropusi partszegely"],
      ro: ["Lamantini", "Ape linistite de rau", "Vegetatie tropicala de mal"],
      en: ["Manatees", "Calm river water", "Tropical riverbank vegetation"]
